// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.sparql.ast;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.stream.Stream;

import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.TestFactory;

class SyntaxTreeBuilderTokenManagerTest implements SyntaxTreeBuilderConstants {

	@TestFactory
	Stream<DynamicTest> recognizesLexemesAcrossCharacterRanges() {
		return lexemes().map(lexeme -> DynamicTest.dynamicTest(lexeme.text(), () -> {
			String text = lexeme.text();
			int expectedKind = lexeme.kind();
			SyntaxTreeBuilderTokenManager lexer = lexer("# comment\r\n\t" + text + " # trailing comment");
			Token token = lexer.getNextToken();
			assertEquals(expectedKind, token.kind);
			assertEquals(text, token.image);
			assertEquals(2, token.beginLine);
			assertEquals(2, token.beginColumn);
			assertEquals(EOF, lexer.getNextToken().kind);
		}));
	}

	static Stream<Lexeme> lexemes() {
		return Stream.of(
				new Lexeme("<http://example.org/é/名>", Q_IRI_REF),
				new Lexeme("ex:", PNAME_NS),
				new Lexeme("é:名", PNAME_LN),
				new Lexeme("ex:select", PNAME_LN),
				new Lexeme("ex:a%20b", PNAME_LN),
				new Lexeme("ex:a\\~b", PNAME_LN),
				new Lexeme("_:名", BLANK_NODE_LABEL),
				new Lexeme("?é", VAR1),
				new Lexeme("$名", VAR2),
				new Lexeme("@en-US", LANGTAG),
				new Lexeme("123", INTEGER),
				new Lexeme("+123", INTEGER_POSITIVE),
				new Lexeme("-123", INTEGER_NEGATIVE),
				new Lexeme(".25", DECIMAL),
				new Lexeme("+.25", DECIMAL_POSITIVE),
				new Lexeme("-.25", DECIMAL_NEGATIVE),
				new Lexeme("1.25e-3", DOUBLE),
				new Lexeme("+1e3", DOUBLE_POSITIVE),
				new Lexeme("-1.e+3", DOUBLE_NEGATIVE),
				new Lexeme("'é\\n名'", STRING_LITERAL1),
				new Lexeme("\"é\\\"名\"", STRING_LITERAL2),
				new Lexeme("'''é\n名'''", STRING_LITERAL_LONG1),
				new Lexeme("\"\"\"é\r\n名\"\"\"", STRING_LITERAL_LONG2),
				new Lexeme("sElEcT", SELECT),
				new Lexeme("nOt", NOT_FUNC),
				new Lexeme("eXiStS", EXISTS));
	}

	@TestFactory
	Stream<DynamicTest> rejectsMalformedLexemes() {
		return Stream.of("\"unterminated", "'line\nbreak'", "\\", "`", "\u0000")
				.map(text -> DynamicTest.dynamicTest("Malformed: " + text,
						() -> assertThrows(TokenMgrError.class, () -> lexer(text).getNextToken())));
	}

	private record Lexeme(String text, int kind) {
	}

	private static SyntaxTreeBuilderTokenManager lexer(String text) {
		return new SyntaxTreeBuilderTokenManager(new UnicodeEscapeStream(text, 1));
	}
}
